<?php
require dirname(__DIR__).'/private/bootstrap.php';require_once dirname(__DIR__).'/private/assessments.php';
if((settings()['environment']??'')!=='development'||!str_ends_with(settings()['dsn'],'/terms.sqlite'))throw new Exception('Isolated fixture only');
$count=0;foreach(term_courses() as $cid=>$course){$off=query('SELECT id FROM term_offerings WHERE course_id=? LIMIT 1',[$cid])->fetchColumn();foreach(array_merge(array_map(fn($i)=>'w'.sprintf('%02d',$i),range(1,10)),['m','f']) as $part){$p=assessment_paper(term_assessment_key($off,$part),true);$answers=[];$ids=[];foreach($p['questions'] as $q){if(in_array($q['id'],$ids,true))throw new Exception('Duplicate question');$ids[]=$q['id'];foreach($q['sources'] as $source)if(!isset($course['sources'][$source]))throw new Exception('Missing reference');$answers[$q['id']]=['value'=>$q['type']==='statements'?array_column($q['statements'],'correct'):$q['correct'],'timedOut'=>false];$public=json_encode(assessment_question_public($q));if(preg_match('/"(?:correct|explanation|sources)":/',$public))throw new Exception('Private key leaked');}$result=assessment_grade($p,$answers);if($result['percent']!==100.0)throw new Exception('Perfect paper failed');if($part!=='f'){$first=$p['questions'][0];$answers[$first['id']]['value']=!$first['correct'];if(assessment_grade($p,$answers)['passed'])throw new Exception('Non-perfect checkpoint passed');}else{if(assessment_maximum($p)!==55)throw new Exception('Wrong final marks');for($i=0;$i<8;$i++){$q=$p['questions'][$i];$answers[$q['id']]['value']=($q['correct']+1)%4;}if(!assessment_grade($p,$answers)['passed'])throw new Exception('47 marks rejected');$q=$p['questions'][8];$answers[$q['id']]['value']=($q['correct']+1)%4;if(assessment_grade($p,$answers)['passed'])throw new Exception('46 marks passed');}$count++;}}
echo "PASS: all $count standard-course papers, 400 weekly questions, four midterms, four 55-mark finals, private active payloads, source IDs and pass thresholds.\n";
